<script>(function(){const category=document.getElementById('classification_category'),subcategory=document.getElementById('classification_subcategory'),phase=document.getElementById('project_phase_id'),entry=document.getElementById('internal_budget_entry_id');function filterSubs(){Array.from(subcategory.options).forEach(o=>{if(!o.value)return;o.hidden=o.dataset.parent!==category.value;if(o.hidden&&o.selected)subcategory.value='';});}category.addEventListener('change',filterSubs);filterSubs();entry.addEventListener('change',function(){const selected=entry.options[entry.selectedIndex];if(!selected.value)return;phase.value=selected.dataset.phase;category.value=selected.dataset.category;filterSubs();subcategory.value=selected.dataset.subcategory||'';});})();</script>
